# Blaze SDK React Native

Blaze SDK React Native is a SDK which helps you integrate Breeze 1CCO and its services seamlessly to your React Native app running on Android/iOS.

## React Native SDK Integration

Follow the below steps to integrate Blaze SDK into your React Native application:

### Step 1: Obtaining the Blaze SDK

In your react native project directory, run the following command:

```bash
npm install @juspay/blaze-sdk-react-native
```

### Step 2: Initialize the SDK

#### 2.2.1: Construct the Initiate Payload

Create a Json with correct parameters to initiate the SDK. This is the data that will be used to initialize the SDK.

```javascript
// Create a JSONObject for the Initiate data
const initiatePayload = {
  merchantId: "<MERCHANT_ID>",
  environment: "<ENVIRONMENT>",
  shopUrl: "<SHOP_URL>"
};

// Place Initiate Payload into SDK Payload
const initSDKPayload = {
  requestId: "<UNIQUE_RANDOM_ID>",
  service: "in.breeze.onecco",
  payload: initiatePayload
};

```

Note: Obtain values for `merchantId`, `environment` and `shopUrl` from the Breeze team.

Refer to schemas for understanding what keys mean.

#### 2.2.2: Construct the Callback Method

During the user journey the SDK will call the callback method with the result of the SDK operation.
You need to implement this method in order to handle the result of the SDK operation.

```javascript
function blazeCallbackHandler(event) {
  const eventName = event.payload?.eventName;

  switch (eventName) {
    // Handle various events according to your desired logic
  }
}
```

#### 2.2.3: Call the initiate method on Blaze Instance

Finally, call the initiate method with the payload and the callback method.
The first parameter is the context of the application.

```javascript
// imports
import BlazeSDK from 'blaze-sdk-react-native';

BlazeSDK.initiate(initSDKPayload, blazeCallbackHandler);
```

### Step 3: Start processing your requests

Once the SDK is initiated, you can start processing your requests using the initialized instance of the SDK.
The SDK will call the callback method with the result of the SDK operation.

#### 3.1: Construct the Process Payload

Create a Json payload with the required parameters to process the request.
The process payload differs based on the request.
Refer to schemas sections to understand what kind of data is required for different requests

```kotlin

// 3.1 Create SDK Process Payload
// Create a JSONObject for the Process data
const processPayload = {};
processPayload.action = "<ACTION>";
// and more parameters required as per the action

// Place Process Payload into SDK Payload
const processSDKPayload = {
  requestId: "<UNIQUE_RANDOM_ID>",
  service: "in.breeze.onecco",
  payload: processPayload
};

```

#### 3.2: Call the process method

Call the process method on the Blaze instance with the process payload to start the user journey or a headless flow.

```javascript
BlazeSDK.process(processSDKPayload)
```

### Step 4: Handling Hardware  Back Press

For making the hardware back button work as expected, you need to call the `handleBackPress` method on the Blaze instance.
The method should be called in the `hardwareBackPress` event listener of your screen.
This method returns a boolean value which indicates if you need to handle back press or not.

```javascript
BackHandler.addEventListener('hardwareBackPress', () => {
  const handleBackPress = BlazeSDK.handleBackPress();
  if (handleBackPress) {
    // write your back press handling logic here
    return false;
  }
  // Skip Back press events if Blaze SDK is handling it
  return true;
});
```

import { NativeModules, DeviceEventEmitter } from 'react-native';

const mockNativeModule = {
  initiate: jest.fn(),
  process: jest.fn(),
  handleBackPress: jest.fn(),
  terminate: jest.fn(),
  addListener: jest.fn(),
  removeListeners: jest.fn(),
};

NativeModules.BlazeSdkReactNative = mockNativeModule;

// The SDK subscribes to the native event emitter at import time, so it must
// be loaded after the native module mock is installed.
const BlazeSDK: typeof import('../index').default = require('../index').default;

describe('BlazeSDK', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  describe('initiate', () => {
    it('forwards the payload to the native module as a JSON string', () => {
      const payload = { requestId: 'abc', service: 'in.breeze.onecco' };

      BlazeSDK.initiate(payload, jest.fn());

      expect(mockNativeModule.initiate).toHaveBeenCalledTimes(1);
      expect(mockNativeModule.initiate).toHaveBeenCalledWith(
        JSON.stringify(payload)
      );
    });

    it('invokes the callback with parsed data on a blaze-callback event', () => {
      const callback = jest.fn();
      BlazeSDK.initiate({}, callback);

      DeviceEventEmitter.emit(
        'blaze-callback',
        JSON.stringify({ event: 'initiate-result', status: 'SUCCESS' })
      );

      expect(callback).toHaveBeenCalledTimes(1);
      expect(callback).toHaveBeenCalledWith({
        event: 'initiate-result',
        status: 'SUCCESS',
      });
    });

    it('replaces the registered callback on subsequent calls', () => {
      const first = jest.fn();
      const second = jest.fn();
      BlazeSDK.initiate({}, first);
      BlazeSDK.initiate({}, second);

      DeviceEventEmitter.emit('blaze-callback', '{}');

      expect(first).not.toHaveBeenCalled();
      expect(second).toHaveBeenCalledWith({});
    });

    it('invokes the callback with an empty object for malformed JSON', () => {
      const callback = jest.fn();
      BlazeSDK.initiate({}, callback);

      DeviceEventEmitter.emit('blaze-callback', 'not-json{');

      expect(callback).toHaveBeenCalledWith({});
    });

    it('ignores events whose data is not a string', () => {
      const callback = jest.fn();
      BlazeSDK.initiate({}, callback);

      DeviceEventEmitter.emit('blaze-callback', { already: 'parsed' });

      expect(callback).not.toHaveBeenCalled();
    });
  });

  describe('process', () => {
    it('forwards the payload to the native module as a JSON string', () => {
      const payload = { action: 'startCheckout' };

      BlazeSDK.process(payload);

      expect(mockNativeModule.process).toHaveBeenCalledTimes(1);
      expect(mockNativeModule.process).toHaveBeenCalledWith(
        JSON.stringify(payload)
      );
    });
  });

  describe('handleBackPress', () => {
    it('returns the native module result', () => {
      mockNativeModule.handleBackPress.mockReturnValueOnce(true);
      expect(BlazeSDK.handleBackPress()).toBe(true);

      mockNativeModule.handleBackPress.mockReturnValueOnce(false);
      expect(BlazeSDK.handleBackPress()).toBe(false);
    });
  });

  describe('terminate', () => {
    it('calls the native module', () => {
      BlazeSDK.terminate();

      expect(mockNativeModule.terminate).toHaveBeenCalledTimes(1);
    });
  });
});

import BlazeSDK
import Foundation
import React

@objc(BlazeSdkReactNative)
class BlazeSdkReactNative: RCTEventEmitter {

  private var blaze: Blaze?

  override static func requiresMainQueueSetup() -> Bool {
    return true
  }

  override func supportedEvents() -> [String]! {
    return ["blaze-callback"]
  }


  @objc
  override static func moduleName() -> String! {
    return "BlazeSdkReactNative"
  }

  @objc
  func initiate(_ initiatePayload: String) {
    blaze = Blaze()
    let initiatePayloadJson = safeParseJson(initiatePayload)
    DispatchQueue.main.async {
      if let blaze = self.blaze,
        let rootViewController = UIApplication.shared.delegate?.window??
          .rootViewController
      {
        blaze.initiate(
          context: rootViewController, initiatePayload: initiatePayloadJson
        ) { result in
            if let resultData = try? JSONSerialization.data(withJSONObject: result, options: []),
             let resultString = String(data: resultData, encoding: .utf8) {
              self.sendEvent(withName: "blaze-callback", body: resultString)
            }
        }
      }
    }
  }

  @objc
  func process(_ processPayload: String) {
    let processPayloadJson = safeParseJson(processPayload)
    blaze?.process(payload: processPayloadJson)
  }

  @objc
  func handleBackPress() -> Bool {
    return true
  }

  @objc
  func terminate() {
    blaze?.terminate()
  }

  // Utility method to parse JSON
  func safeParseJson(_ jsonString: String) -> [String: Any] {
    if let data = jsonString.data(using: .utf8) {
      do {
        if let json = try JSONSerialization.jsonObject(with: data, options: [])
          as? [String: Any]
        {
          return json
        }
      } catch {
        print("JSON parsing error: \(error)")
      }
    }
    return [:]
  }
}

